# GENERATED by scripts/oss/assemble_public_tree.py from the platform repository's .circleci/select_checks.py (#2428).
"""Generate a conservative CircleCI workflow; unknown changes run all checks."""
from __future__ import annotations

import argparse
import json
import subprocess
from pathlib import Path

import yaml

ALL = {"python", "public", "public-e2e", "package", "docker"}

#: Process and documentation paths: nothing a job validates reads them, so they
#: select only the policy job that every pipeline runs. Before 2026-10-12 an
#: unrecognised path selected every job including the Docker image build, which
#: is why CircleCI was paused (#2277).
_POLICY_ONLY_PREFIXES = (
    "docs/", ".agents/", ".claude/", ".codex/", ".github/", "design/", "deploy/helm/",
)
_POLICY_ONLY_FILES = {
    "README.md", "CLAUDE.md", "AGENTS.md", "CONTRIBUTING.md", "SECURITY.md", "LICENSE",
    "NOTICE", ".gitignore", ".editorconfig", "renovate.json", ".pre-commit-config.yaml",
}
#: Inputs of the engine image: only these select the Docker job.
_IMAGE_PREFIXES = ("deploy/light/", "deploy/stage_venv_overlay.py")


def _is_policy_only(path: str) -> bool:
    if path in _POLICY_ONLY_FILES or path.startswith(_POLICY_ONLY_PREFIXES):
        return True
    return path.endswith(".md") and "/" not in path


def select(paths: list[str], *, full: bool = False) -> set[str]:
    """Select consumers as well as producers; an unknown path never skips work."""
    if full or not paths:
        return set(ALL)
    jobs: set[str] = set()
    for path in paths:
        if _is_policy_only(path):
            continue
        if path.startswith(("src/", "tests/", "packages/", "examples/", "scripts/")):
            jobs.add("python")
            if path.endswith(("pyproject.toml", "pack.toml")):
                jobs.update(ALL)
        elif path in (".semgrep.yml", "Makefile"):
            jobs.add("python")
        elif (path.startswith(("Dockerfile", "docker-compose")) or path == ".dockerignore"
              or path.startswith(_IMAGE_PREFIXES)):
            jobs.add("docker")
        else:
            # pyproject.toml, uv.lock, cairn.lock, .circleci/, anything new
            jobs.update(ALL)
    if "python" in jobs:
        # whatever can break the full install can break the public set (#2424), and the
        # public set's behaviour is proved by the e2e cells (ADR-0127 D1)
        jobs.update({"public", "public-e2e"})
    return jobs


def generate(template: dict, jobs: set[str], *, main: bool = False) -> dict:
    """Require every selected job before emitting the stable readiness result."""
    workflow: list = ["policy"]
    required = ["policy"]
    for name in sorted(jobs):
        workflow.append({name: {"requires": ["policy"]}})
        required.append(name)
    if main and "python" in jobs:
        workflow.append({"python": {"name": "python-312", "python-version": "3.12", "requires": ["policy"]}})
        required.append("python-312")
        workflow.append({"python": {"name": "python-314", "python-version": "3.14", "requires": ["policy"]}})
        required.append("python-314")
    workflow.append({"ready": {"requires": required}})
    return {**template, "workflows": {"cairn-validation": {"jobs": workflow}}}


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--branch", required=True)
    args = parser.parse_args()
    # v1 supports main-target PRs. Run the full pipeline if the base cannot be
    # fetched/resolved; never convert an empty or failed comparison into docs-only.
    paths: list[str] = []
    full = args.branch == "main"
    base = ""
    if not full:
        try:
            subprocess.run(["git", "fetch", "origin", "main:refs/remotes/origin/main"], check=True)
            base = subprocess.check_output(["git", "merge-base", "origin/main", "HEAD"], text=True).strip()
            paths = subprocess.check_output(["git", "diff", "--name-only", "--no-renames", "-z", base, "HEAD"]).decode().split("\0")
            paths = [p for p in paths if p]
        except subprocess.CalledProcessError:
            full = True
    jobs = select(paths, full=full)
    template = yaml.safe_load(Path(".circleci/jobs.yml").read_text())
    Path("/tmp/cairn-continue.yml").write_text(yaml.safe_dump(generate(template, jobs, main=args.branch == "main"), sort_keys=False))
    Path("/tmp/cairn-selection.json").write_text(json.dumps({"base": base, "paths": paths, "jobs": sorted(jobs), "full": full}, indent=2))
    print("Selected:", ", ".join(sorted(jobs)) or "policy only")


if __name__ == "__main__":
    main()
